-- Referenciamunkák: kizárólag saját ERP-adatok; helyi médiabájtok.
begin;
create table erp."references"(id uuid primary key,organization_id uuid not null,project_id uuid not null,revision bigint not null default 0,base_revision bigint not null default 0,title text not null,archived boolean not null default false,created_by uuid not null,updated_at timestamptz not null default clock_timestamp(),unique(organization_id,id),foreign key(organization_id,project_id)references erp.garden_projects(organization_id,id),foreign key(organization_id,created_by)references erp.persons(organization_id,id));
create index references_projects on erp."references"(organization_id,project_id,updated_at desc,id);
create index references_creator on erp."references"(organization_id,created_by);
create table erp.reference_versions(organization_id uuid not null,reference_id uuid not null,revision bigint not null,document jsonb not null,source_hash text not null,source_survey uuid,actor_id uuid not null,created_at timestamptz not null default clock_timestamp(),primary key(organization_id,reference_id,revision),foreign key(organization_id,reference_id)references erp."references"(organization_id,id),foreign key(organization_id,actor_id)references erp.persons(organization_id,id),foreign key(organization_id,source_survey)references erp.surveys(organization_id,id),check(jsonb_typeof(document)='object' and octet_length(document::text)<=250000));
create index reference_versions_survey on erp.reference_versions(organization_id,source_survey);
create index reference_versions_actor on erp.reference_versions(organization_id,actor_id);
create table erp.reference_variants(organization_id uuid not null,reference_id uuid not null,platform text not null check(platform in('web','facebook','instagram')),revision bigint not null,base_revision bigint not null,primary key(organization_id,reference_id,platform),foreign key(organization_id,reference_id,base_revision)references erp.reference_versions(organization_id,reference_id,revision));
create table erp.reference_variant_versions(organization_id uuid not null,reference_id uuid not null,platform text not null,revision bigint not null,document jsonb not null,actor_id uuid not null,created_at timestamptz not null default clock_timestamp(),primary key(organization_id,reference_id,platform,revision),foreign key(organization_id,reference_id,platform)references erp.reference_variants(organization_id,reference_id,platform),foreign key(organization_id,actor_id)references erp.persons(organization_id,id),check(jsonb_typeof(document)='object' and octet_length(document::text)<=250000));
create index reference_variant_actor on erp.reference_variant_versions(organization_id,actor_id);
create table erp.reference_media(organization_id uuid not null,reference_id uuid not null,id uuid not null,document jsonb not null,removed boolean not null default false,primary key(organization_id,reference_id,id),foreign key(organization_id,reference_id)references erp."references"(organization_id,id),check(octet_length(document::text)<6000));
create table erp.reference_publication_approvals(id uuid primary key,organization_id uuid not null,reference_id uuid not null,platform text not null,reference_revision bigint not null,variant_revision bigint not null,manifest_hash text not null,evidence text not null check(length(btrim(evidence))between 1 and 2000),actor_id uuid not null,created_at timestamptz not null default clock_timestamp(),foreign key(organization_id,reference_id,platform,variant_revision)references erp.reference_variant_versions(organization_id,reference_id,platform,revision),foreign key(organization_id,actor_id)references erp.persons(organization_id,id));
create index reference_approval_lookup on erp.reference_publication_approvals(organization_id,reference_id,platform,reference_revision);
create index reference_approval_variant on erp.reference_publication_approvals(organization_id,reference_id,platform,variant_revision);
create index reference_approval_actor on erp.reference_publication_approvals(organization_id,actor_id);
create table erp_private.reference_commands(request_id uuid primary key,organization_id uuid not null,reference_id uuid not null,actor_auth_id uuid not null,request_hash text not null,result jsonb not null,created_at timestamptz not null default clock_timestamp(),foreign key(organization_id,reference_id)references erp."references"(organization_id,id));
create index reference_commands_ref on erp_private.reference_commands(organization_id,reference_id);
create table erp_private.reference_publications(id uuid primary key,organization_id uuid not null,reference_id uuid not null,reference_revision bigint not null,variant_revision bigint not null,kind text not null check(kind in('media','draft','publish')),media_id uuid,status text not null check(status in('started','succeeded','uncertain','failed')),remote_id bigint,remote_modified text,remote_status text,remote_url text,error text,created_at timestamptz not null default clock_timestamp(),foreign key(organization_id,reference_id)references erp."references"(organization_id,id),foreign key(organization_id,reference_id,media_id)references erp.reference_media(organization_id,reference_id,id),check(remote_id is null or remote_id>0),check(length(error)<=1000));
create index reference_publications_ref on erp_private.reference_publications(organization_id,reference_id,created_at desc,id);
create index reference_publications_media on erp_private.reference_publications(organization_id,reference_id,media_id);
create table erp_private.reference_publication_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null,publication_id uuid not null references erp_private.reference_publications(id),actor_id uuid not null,kind text not null,data jsonb not null,created_at timestamptz not null default clock_timestamp(),foreign key(organization_id,actor_id)references erp.persons(organization_id,id));
create index reference_publication_event on erp_private.reference_publication_events(publication_id,created_at);
create index reference_publication_event_actor on erp_private.reference_publication_events(organization_id,actor_id);

do $$declare t text;begin foreach t in array array['references','reference_versions','reference_variants','reference_variant_versions','reference_media','reference_publication_approvals']loop execute format('alter table erp.%I enable row level security',t);execute format('alter table erp.%I force row level security',t);execute format('revoke all on erp.%I from public,anon,authenticated,service_role',t);end loop;foreach t in array array['reference_commands','reference_publications','reference_publication_events']loop execute format('alter table erp_private.%I enable row level security',t);execute format('alter table erp_private.%I force row level security',t);execute format('revoke all on erp_private.%I from public,anon,authenticated,service_role',t);end loop;end$$;

create function erp_private.reference_source(p_org uuid,p_project uuid,p_survey uuid default null)returns jsonb language plpgsql stable security definer set search_path='' as $$declare g erp.garden_projects;w erp.workplans;q erp.quote_versions;survey_doc jsonb;survey_ref jsonb;sid uuid;srev int;tasks jsonb;materials jsonb;photos jsonb;units jsonb;accepted jsonb;result jsonb;begin
 select * into g from erp.garden_projects where organization_id=p_org and id=p_project and work_type='construction'and accepted_quote_id is not null;if not found then raise exception 'A kertépítés nem érhető el.' using errcode='42501';end if;
 select * into q from erp.quote_versions where organization_id=p_org and quote_id=g.accepted_quote_id and version=g.accepted_quote_version;
 select * into w from erp.workplans where organization_id=p_org and project_id=g.id;
 survey_ref:=q.input->'source_survey';sid:=nullif(survey_ref->>'id','')::uuid;srev:=nullif(survey_ref->>'revision','')::int;
 if p_survey is not null then sid:=p_survey;select revision into srev from erp.surveys where organization_id=p_org and id=sid and source_customer_id=g.source_customer_id and source_location_id=g.source_location_id;if not found then raise exception 'Másik ügyfél vagy cím felmérése nem választható.' using errcode='42501';end if;end if;
 select v.document into survey_doc from erp.survey_versions v join erp.surveys s on s.organization_id=v.organization_id and s.id=v.survey_id where v.organization_id=p_org and v.survey_id=sid and v.revision=srev and s.source_customer_id=g.source_customer_id and s.source_location_id=g.source_location_id;
 units:=case when w.id is null then '[]'::jsonb else erp_private.execution_current_units(w.id)end;accepted:=erp_private.execution_balance(units)->'accepted_parents';
 select coalesce(jsonb_agg(jsonb_build_object('id',t.id,'source_line_id',t.source_line_id,'title',coalesce(erp_private.plan_task_json(t)->>'contract_label',t.title),'section',erp_private.plan_task_json(t)->>'section','quantity',erp_private.plan_task_json(t)->>'quantity','unit',erp_private.plan_task_json(t)->>'unit','accepted',accepted ? t.id::text)order by t.sort,t.id),'[]')into tasks from erp.project_tasks t where t.plan_id=w.id and erp_private.entry_task_active(t.id);
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'unit',unit,'installed',installed::text)order by name,id),'[]')into materials from(select l.id,l.name,l.unit,sum(b.installed)installed from erp.project_material_plans p join erp.project_material_lines l on l.plan_id=p.id join erp.material_lots b on b.line_id=l.id where p.organization_id=p_org and p.project_id=p_project group by l.id,l.name,l.unit having sum(b.installed)>0)x;
 select coalesce(jsonb_agg(jsonb_build_object('id',m->>'id','mime',m->>'mime','bytes',m->'size','sha256',m->>'sha256','source','survey')order by m->>'id'),'[]')into photos from jsonb_array_elements(coalesce(survey_doc->'sections','[]'))s cross join lateral jsonb_array_elements(coalesce(s->'media','[]'))m where m->>'kind'='photo';
 select photos||coalesce(jsonb_agg(item),'[]')into photos from(select distinct on(m->>'id')jsonb_build_object('id',m->>'id','mime',m->>'mime','bytes',m->'bytes','sha256',m->>'sha256','source','project')item from(
 select coalesce(e.request_payload->'command'->'media',e.request_payload->'media','[]'::jsonb)media from erp.task_events e where e.organization_id=p_org and e.project_id=p_project
 union all select coalesce(v.payload->'media','[]'::jsonb)from erp.project_entries e join erp.project_entry_versions v on v.organization_id=e.organization_id and v.entry_id=e.id and v.version=e.current_version where e.organization_id=p_org and e.project_id=p_project
 )events cross join lateral jsonb_array_elements(events.media)m where m->>'mime'in('image/jpeg','image/png','image/webp'))p;
 result:=jsonb_build_object('project_id',p_project,'quote_id',g.accepted_quote_id,'quote_version',g.accepted_quote_version,'plan_revision',w.revision,'survey_id',case when survey_doc is null then null else sid end,'survey_revision',case when survey_doc is null then null else srev end,'surveys',coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'title',s.document->>'title')order by s.updated_at desc)from erp.surveys s where s.organization_id=p_org and s.source_customer_id=g.source_customer_id and s.source_location_id=g.source_location_id),'[]'),'wishes',coalesce(survey_doc->>'wishes',''),'tasks',tasks,'materials',materials,'photos',photos);
 if octet_length(result::text)>2000000 then raise exception 'A forrás túl nagy. Kérj külön feldolgozást.' using errcode='22023';end if;return result||jsonb_build_object('hash',md5(result::text));
end$$;
create function public.erp_reference_list(p_org uuid,p_actor uuid,p_filter jsonb default '{}')returns jsonb language plpgsql stable security definer set search_path='' as $$declare result jsonb;begin
 perform erp_private.require_customer_office(p_org,p_actor);
 return jsonb_build_object('projects',coalesce((select jsonb_agg(jsonb_build_object('id',g.id,'name',g.name,'address',g.site_address)order by g.name,g.id)from erp.garden_projects g where g.organization_id=p_org and g.work_type='construction' and g.accepted_quote_id is not null),'[]'),'references',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'project_id',r.project_id,'title',r.title,'revision',r.revision,'archived',r.archived,'updated_at',r.updated_at)order by r.updated_at desc,r.id)from erp."references"r where r.organization_id=p_org and r.archived=coalesce((p_filter->>'archived')::boolean,false)),'[]'));
end$$;
create function public.erp_reference_source(p_org uuid,p_actor uuid,p_project uuid,p_survey uuid default null)returns jsonb language plpgsql stable security definer set search_path='' as $$begin perform erp_private.require_customer_office(p_org,p_actor);return erp_private.reference_source(p_org,p_project,p_survey);end$$;
create function public.erp_reference_read(p_org uuid,p_actor uuid,p_reference uuid,p_filter jsonb default '{}')returns jsonb language plpgsql stable security definer set search_path='' as $$declare r erp."references";doc jsonb;origin text;chosen_survey uuid;variants jsonb;off int;begin
 perform erp_private.require_customer_office(p_org,p_actor);select * into r from erp."references"where organization_id=p_org and id=p_reference;if not found then raise exception 'A referencia nem érhető el.' using errcode='42501';end if;off:=coalesce((p_filter->>'offset')::int,0);if off<0 or off>100000 then raise exception 'Hibás előzménylap.' using errcode='22023';end if;
 select document,source_hash,source_survey into doc,origin,chosen_survey from erp.reference_versions where organization_id=p_org and reference_id=r.id and revision=coalesce((p_filter->>'base_revision')::bigint,r.base_revision);if doc is null then raise exception 'A változat nem található.' using errcode='22023';end if;
 select coalesce(jsonb_object_agg(v.platform,jsonb_build_object('revision',v.revision,'base_revision',v.base_revision,'document',d.document)),'{}')into variants from erp.reference_variants v join erp.reference_variant_versions d on d.organization_id=v.organization_id and d.reference_id=v.reference_id and d.platform=v.platform and d.revision=case when p_filter->>'platform'=v.platform then coalesce((p_filter->>'variant_revision')::bigint,v.revision)else v.revision end where v.organization_id=p_org and v.reference_id=r.id;
 return jsonb_build_object('id',r.id,'project_id',r.project_id,'revision',r.revision,'base_revision',r.base_revision,'archived',r.archived,'document',doc,'source_hash',origin,'variants',variants,'history',coalesce((select jsonb_agg(x)from(select revision,created_at from erp.reference_versions where organization_id=p_org and reference_id=r.id order by revision desc limit 50 offset off)x),'[]'),'variant_history',coalesce((select jsonb_agg(x)from(select platform,revision,created_at from erp.reference_variant_versions where organization_id=p_org and reference_id=r.id order by revision desc limit 50 offset off)x),'[]'),'source',erp_private.reference_source(p_org,r.project_id,chosen_survey),'survey_id',chosen_survey,'approvals',coalesce((select jsonb_agg(jsonb_build_object('platform',a.platform,'reference_revision',a.reference_revision,'variant_revision',a.variant_revision,'manifest_hash',a.manifest_hash))from erp.reference_publication_approvals a where a.organization_id=p_org and a.reference_id=r.id and a.reference_revision=r.revision),'[]'),'publications',coalesce((select jsonb_agg(x)from(select id,kind,media_id,status,reference_revision,variant_revision,remote_id,remote_modified,remote_status,remote_url,error from erp_private.reference_publications where organization_id=p_org and reference_id=r.id and(status in('started','uncertain')or id in(select distinct on(media_id)id from erp_private.reference_publications where organization_id=p_org and reference_id=r.id and kind='media'and status='succeeded'order by media_id,created_at desc,id desc)or id=(select id from erp_private.reference_publications where organization_id=p_org and reference_id=r.id and kind in('draft','publish')and status='succeeded'order by created_at desc,id desc limit 1)or id in(select id from erp_private.reference_publications where organization_id=p_org and reference_id=r.id and status='failed'order by created_at desc,id desc limit 20))order by created_at desc,id desc)x),'[]'));
end$$;

create function erp_private.reference_validate(p_doc jsonb,p_variant boolean default false)returns void language plpgsql immutable security invoker set search_path='' as $$declare x jsonb;k text;begin
 if jsonb_typeof(p_doc)is distinct from 'object' or octet_length(p_doc::text)>250000 then raise exception 'Hibás referencia.' using errcode='22023';end if;
 if exists(select 1 from jsonb_object_keys(p_doc)field_name where field_name<>all(case when p_variant then array['platform','title','body','seo_title','seo_description','tags','photos']else array['version','title','wishes','realization','materials','media']end))then raise exception 'Nem engedélyezett referenciamező.' using errcode='22023';end if;
 if p_variant then
 if coalesce(p_doc->>'platform','')not in('web','facebook','instagram')or jsonb_typeof(p_doc->'photos')is distinct from 'array'or jsonb_array_length(p_doc->'photos')>200 or jsonb_typeof(p_doc->'tags')is distinct from 'array'or jsonb_array_length(p_doc->'tags')>40 then raise exception 'Hibás változat.' using errcode='22023';end if;
 foreach k in array array['title','body','seo_title','seo_description']loop if jsonb_typeof(p_doc->k)is distinct from 'string'or length(p_doc->>k)>(case when k='body'then 40000 when k='seo_description'then 500 else 200 end) then raise exception 'Hibás változatszöveg.' using errcode='22023';end if;end loop;
 else
 if p_doc->>'version'is distinct from '1'or length(btrim(coalesce(p_doc->>'title','')))not between 1 and 200 or jsonb_typeof(p_doc->'media')is distinct from 'array'or jsonb_array_length(p_doc->'media')>200 then raise exception 'Hibás referencia.' using errcode='22023';end if;
 foreach k in array array['wishes','realization','materials']loop if jsonb_typeof(p_doc->k)is distinct from 'string'or length(p_doc->>k)>(case when k='wishes'then 10000 when k='realization'then 30000 else 15000 end) then raise exception 'Hibás referenciaszöveg.' using errcode='22023';end if;end loop;
 for x in select value from jsonb_array_elements(p_doc->'media')loop if(x->>'id')::uuid is null or coalesce(x->>'group','')not in('before','during','after','later')or x->>'mime'is distinct from 'image/jpeg'or coalesce((x->>'bytes')::int,0) not between 1 and 4194304 or coalesce(x->>'sha256','')!~'^[a-f0-9]{64}$'or length(x->>'caption')>500 or length(x->>'alt')>500 then raise exception 'Hibás fénykép.' using errcode='22023';end if;end loop;
 if(select count(*)from jsonb_array_elements(p_doc->'media'))<>(select count(distinct item->>'id')from jsonb_array_elements(p_doc->'media')item)then raise exception 'Ismétlődő fénykép.' using errcode='22023';end if;
 end if;
end$$;
create function public.erp_reference_write(p_org uuid,p_actor uuid,p_reference uuid,p_project uuid,p_request uuid,p_revision bigint,p_command jsonb)returns jsonb language plpgsql security definer set search_path='' as $$declare r erp."references";prior erp_private.reference_commands;person uuid;hash text;op text;doc jsonb;base jsonb;source text;chosen_survey uuid;target_platform text;m jsonb;v erp.reference_variants;result jsonb;begin
 perform erp_private.require_customer_office(p_org,p_actor);select person_id into person from erp.user_accounts where organization_id=p_org and auth_user_id=p_actor and active;op:=p_command->>'kind';if p_request is null or p_reference is null or op not in('save','variant','archive','approve')or jsonb_typeof(p_command)is distinct from 'object' then raise exception 'Hibás mentési kérés.' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('erp-reference:'||p_reference::text,0));hash:=md5(jsonb_build_object('org',p_org,'reference',p_reference,'project',p_project,'revision',p_revision,'command',p_command)::text);
 select * into prior from erp_private.reference_commands where request_id=p_request;if found then if prior.organization_id<>p_org or prior.actor_auth_id<>p_actor or prior.request_hash<>hash then raise exception 'Eltérő ismételt kérés.' using errcode='40001';end if;return prior.result||'{"replayed":true}';end if;
 select * into r from erp."references"where id=p_reference for update;
 if found then if r.organization_id<>p_org or r.project_id<>p_project then raise exception 'Másik szervezet referenciája.' using errcode='42501';end if;else
 if op<>'save'or p_revision<>0 then raise exception 'Először mentsd a referencia alapját.' using errcode='22023';end if;perform erp_private.reference_source(p_org,p_project);insert into erp."references"(id,organization_id,project_id,title,created_by)values(p_reference,p_org,p_project,'Új referencia',person)returning * into r;
 end if;
 if r.revision is distinct from p_revision then raise exception 'A referencia megváltozott. Frissítsd az adatokat.' using errcode='40001';end if;
 select document,source_hash,source_survey into base,source,chosen_survey from erp.reference_versions where organization_id=p_org and reference_id=r.id and revision=r.base_revision;
 if r.archived and op<>'archive'then raise exception 'Előbb állítsd vissza az archivált referenciát.' using errcode='22023';end if;
 if op='save'then
 doc:=p_command->'document';perform erp_private.reference_validate(doc);if p_command ? 'source_hash'then if p_command->>'source_hash' is distinct from erp_private.reference_source(p_org,p_project,nullif(p_command->>'survey_id','')::uuid)->>'hash'then raise exception 'A projekt forrásadata megváltozott. Frissítsd az előnézetet.' using errcode='40001';end if;source:=p_command->>'source_hash';chosen_survey:=nullif(p_command->>'survey_id','')::uuid;end if;if source is null then raise exception 'Hiányzó forrásellenőrzés.' using errcode='22023';end if;
 -- A már mentett platformképeket előbb a saját változatukból kell kivenni.
 if exists(select 1 from erp.reference_variants vv join erp.reference_variant_versions dd on dd.organization_id=vv.organization_id and dd.reference_id=vv.reference_id and dd.platform=vv.platform and dd.revision=vv.revision cross join lateral jsonb_array_elements(dd.document->'photos')ph where vv.organization_id=p_org and vv.reference_id=r.id and not exists(select 1 from jsonb_array_elements(doc->'media')mm where mm->>'id'=ph->>'media_id'))then raise exception 'A képet előbb vedd ki a mentett platformváltozatokból.' using errcode='22023';end if;
 r.revision:=r.revision+1;r.base_revision:=r.revision;r.title:=doc->>'title';insert into erp.reference_versions values(p_org,r.id,r.revision,doc,source,chosen_survey,person,clock_timestamp());
 update erp.reference_media set removed=true where organization_id=p_org and reference_id=r.id;
 for m in select value from jsonb_array_elements(doc->'media')loop
 if exists(select 1 from erp.reference_media where organization_id=p_org and reference_id=r.id and id=(m->>'id')::uuid and(document->>'sha256'is distinct from m->>'sha256'or document->>'bytes'is distinct from m->>'bytes'))then raise exception 'A meglévő kép bájtjai nem írhatók át.' using errcode='22023';end if;
 insert into erp.reference_media values(p_org,r.id,(m->>'id')::uuid,m,false)on conflict(organization_id,reference_id,id)do update set document=excluded.document,removed=false;end loop;
 elsif op='variant'then
 doc:=p_command->'document';perform erp_private.reference_validate(doc,true);target_platform:=doc->>'platform';if exists(select 1 from jsonb_array_elements(doc->'photos')ph where not exists(select 1 from jsonb_array_elements(base->'media')bm where bm->>'id'=ph->>'media_id'))or(select count(*)from jsonb_array_elements(doc->'photos'))<>(select count(distinct x->>'media_id')from jsonb_array_elements(doc->'photos')x)then raise exception 'Ismeretlen vagy ismétlődő kép.' using errcode='22023';end if;
 r.revision:=r.revision+1;insert into erp.reference_variants values(p_org,r.id,target_platform,r.revision,r.base_revision)on conflict(organization_id,reference_id,platform)do update set revision=excluded.revision,base_revision=excluded.base_revision;insert into erp.reference_variant_versions values(p_org,r.id,target_platform,r.revision,doc,person,clock_timestamp());
 elsif op='archive'then if jsonb_typeof(p_command->'archived')is distinct from 'boolean'then raise exception 'Hiányzó archiválási döntés.' using errcode='22023';end if;r.revision:=r.revision+1;r.archived:=(p_command->>'archived')::boolean;
 elsif op='approve'then
 target_platform:=p_command->>'platform';select * into v from erp.reference_variants where organization_id=p_org and reference_id=r.id and reference_variants.platform=target_platform;if not found then raise exception 'Előbb mentsd a publikációs változatot.' using errcode='22023';end if;
 select document into doc from erp.reference_variant_versions where organization_id=p_org and reference_id=r.id and reference_variant_versions.platform=target_platform and revision=v.revision;
 if p_command->'checked'is distinct from 'true'::jsonb or length(btrim(coalesce(p_command->>'evidence','')))not between 1 and 2000 or length(btrim(doc->>'title'))=0 or length(btrim(doc->>'body'))=0 or(target_platform='web'and(length(btrim(doc->>'seo_title'))=0 or length(btrim(doc->>'seo_description'))=0 or exists(select 1 from jsonb_array_elements(doc->'photos')p where length(btrim(p->>'alt'))=0)))then raise exception 'Ellenőrizd a szöveget, képeket, hozzájárulásokat és SEO-adatokat.' using errcode='22023';end if;
 insert into erp.reference_publication_approvals values(p_request,p_org,r.id,target_platform,r.revision,v.revision,md5(jsonb_build_object('variant',doc,'media',base->'media')::text),p_command->>'evidence',person,clock_timestamp());
 end if;
 update erp."references"set revision=r.revision,base_revision=r.base_revision,title=r.title,archived=r.archived,updated_at=clock_timestamp()where id=r.id;result:=jsonb_build_object('id',r.id,'revision',r.revision);insert into erp_private.reference_commands values(p_request,p_org,r.id,p_actor,hash,result,clock_timestamp());return result;
end$$;
-- Külső művelet előtt külön, tartós napló: a bizonytalan kérés nem ismétlődik vakon.
create function public.erp_reference_publication(p_org uuid,p_actor uuid,p_reference uuid,p_request uuid,p_revision bigint,p_command jsonb)returns jsonb language plpgsql security definer set search_path='' as $$declare r erp."references";v erp.reference_variants;j erp_private.reference_publications;person uuid;doc jsonb;base jsonb;kind text;media uuid;begin
 perform erp_private.require_customer_office(p_org,p_actor);select person_id into person from erp.user_accounts where organization_id=p_org and auth_user_id=p_actor and active;perform pg_advisory_xact_lock(hashtextextended('erp-reference:'||p_reference::text,0));select * into r from erp."references"where organization_id=p_org and id=p_reference for update;if not found or r.archived or r.revision is distinct from p_revision then raise exception 'Frissítsd a referenciát.' using errcode='40001';end if;
 select * into v from erp.reference_variants where organization_id=p_org and reference_id=r.id and platform='web';select document into doc from erp.reference_variant_versions where organization_id=p_org and reference_id=r.id and platform='web'and revision=v.revision;select document into base from erp.reference_versions where organization_id=p_org and reference_id=r.id and revision=r.base_revision;
 if not exists(select 1 from erp.reference_publication_approvals a where a.organization_id=p_org and a.reference_id=r.id and a.platform='web'and a.reference_revision=r.revision and a.variant_revision=v.revision and a.manifest_hash=md5(jsonb_build_object('variant',doc,'media',base->'media')::text))then raise exception 'Ehhez a változathoz irodai ellenőrzés szükséges.' using errcode='42501';end if;
 if p_command->>'operation'='begin'then
 if exists(select 1 from erp.reference_versions rv where rv.organization_id=p_org and rv.reference_id=r.id and rv.revision=r.base_revision and rv.source_hash is distinct from erp_private.reference_source(p_org,r.project_id,rv.source_survey)->>'hash')then raise exception 'A projekt forrásadata megváltozott. Ellenőrizd újra a referenciát.' using errcode='40001';end if;
 kind:=p_command->>'kind';media:=nullif(p_command->>'media_id','')::uuid;if kind not in('media','draft','publish')or(kind='media'and not exists(select 1 from jsonb_array_elements(doc->'photos')p where(p->>'media_id')::uuid=media))or p_request is null then raise exception 'Hibás WordPress-művelet.' using errcode='22023';end if;
 if exists(select 1 from erp_private.reference_publications where organization_id=p_org and reference_id=r.id and status in('started','uncertain'))then raise exception 'Az előző küldés eredménye még bizonytalan. Előbb egyeztesd a WordPress-adatot.' using errcode='40001';end if;
 if exists(select 1 from erp_private.reference_publications where id=p_request)then raise exception 'Ezt a külső kérést már elindítottad. Frissítsd az állapotot.' using errcode='40001';end if;
 insert into erp_private.reference_publications(id,organization_id,reference_id,reference_revision,variant_revision,kind,media_id,status)values(p_request,p_org,r.id,r.revision,v.revision,kind,media,'started')returning * into j;
 elsif p_command->>'operation'='finish'then
 select * into j from erp_private.reference_publications where id=p_request and organization_id=p_org and reference_id=r.id for update;if not found or j.status<>'started'or p_command->>'status'not in('succeeded','uncertain','failed')then raise exception 'Hibás küldési állapot.' using errcode='40001';end if;
 update erp_private.reference_publications set status=p_command->>'status',remote_id=nullif(p_command->>'remote_id','')::bigint,remote_modified=left(p_command->>'remote_modified',100),remote_status=left(p_command->>'remote_status',40),remote_url=case when p_command->>'remote_url'~'^https://diszkertek[.]hu/'then left(p_command->>'remote_url',2000)else null end,error=left(p_command->>'error',1000)where id=j.id returning * into j;
 else raise exception 'Ismeretlen küldési művelet.' using errcode='22023';end if;
 insert into erp_private.reference_publication_events(organization_id,publication_id,actor_id,kind,data)values(p_org,j.id,person,p_command->>'operation',jsonb_build_object('status',j.status));return jsonb_build_object('id',j.id,'status',j.status);
end$$;
do $$declare f record;begin for f in select p.oid::regprocedure signature,n.nspname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where(n.nspname='erp_private'and p.proname like 'reference_%')or(n.nspname='public'and p.proname like 'erp_reference_%')loop execute format('revoke all on function %s from public,anon,authenticated,service_role',f.signature);if f.nspname='public'then execute format('grant execute on function %s to service_role',f.signature);end if;end loop;end$$;
commit;
